namespace OpenTPW;

/// <summary>
/// Approximation register of guest arrivals (docs/GUESTS.md, "Arrivals"). Each entry is tagged
/// <c>[APPROX:ARRIVAL-NNN]</c> at its code site; the arrival rule itself is traced from the Mac binary.
/// </summary>
public static class ArrivalApproximations
{
	public static readonly IReadOnlyList<(string Id, string Rule)> Entries = new[]
	{
		("ARRIVAL-008", "THEME PARK INC WEATHER: Theme Park Inc's group size follows its own routine (TPI Game.exe 0x5BCD60: a percentage of the weather state, 0.01 in single precision, divided by the points per visitor; oracle X7), and the weather state is the running spell's kind (+0x70, 1 heatwave, 2 rain, 3 storm, 4 snow; 0x642A80) that the economy now rolls as 0x642770 does ([EXT:tpi-weather-spell-seed]: the original seeds the C runtime rand() with GetTickCount() at 0x6A151B, so its draws cannot be reproduced and the economy's world stream stands in); the routine's other exit is read and ported: the object 0xA06558 is the theme selection of the startup dialog (Arabian 0, Science 1, Water 2, Intro World 3; setter 0x42A360 called by the radio group 0x498940..0x4989CA, -1 becomes 3 at 0x6A32D7) and the Intro World (levels/wIntro, which OpenTPW's front end does not run) has no arrivals (GuestSimulation.IntroWorld); the three words after the Seasons rows are read (the loader writes the array count, 0x419FB4, here 4, and the two online-only keys stay 0 offline); the attractions' weather closing is ported (0x5DED90, message 1 of the attraction's update, once per turn: a spell whose WeatherModifier.ClosedDuringHeatWave, Rain, Storm or Snow word (type +0x100..+0x10C) is 1 closes the attraction and sets its mClosedDueToWeather byte +0x41, and the first update without such a spell opens it again and clears the byte: OriginalObjectRuntime.ApplyWeatherClosing; no shipped Theme Park Inc object sets the keys, only a mod does); the guests' reactions to the spell (0x6103AC, 0x6109D6 the rain times the type word +0xF4, 0x6178DF) belong to the ported Theme Park World guest rules over Theme Park Inc's data ([EXT:tpi-twp-guest-rules], docs/THEME-PARK-INC.md), with the umbrellas and rain-mood extensions; left: the spell's own presentation and per-turn effects are not simulated (the sky quality float +0x74 read at 0x687665 and handed to the sky's light call 0x40AB6E has no counterpart in the slice, which draws no Theme Park Inc sky; drops, lightning and thunder: WeatherEffects.* and Weather.SpeedOfChange, Min/MaxDaysFor*WeatherSpell), and the weather thing's per-turn update and the effect counters it writes (+0x74 and the others) and 0x616DD2 are not read"),
	};
}
